insert into public.projects (id, club_id, title, strand, problem, action, evidence, reflection, status, visibility, year, approved_by, approved_at, created_by, created_at) values
  ('f3a48893-78be-52a8-80e0-c63e3204ea72', '7e0472bd-c496-5fb0-be70-99175fa8757a', 'DEMO · Plastic-free lunch week', 'nature', 'DEMO text. Our canteen hands out single-use plastic at every lunch, and most of it is in the bin the same day.', 'DEMO text. For one week we bring reusable boxes and bottles, run a swap table, and count the plastic we avoid each day.', 'DEMO text. Daily counts on a whiteboard, photos of the swap table, and a short survey of students.', 'DEMO text. Written once the week is over.', 'active', 'public', 2026, 'a06be9e1-75c4-53a1-99da-2bff395d3434', '2026-09-15T10:00:00Z', '74866792-0bc7-5140-8f41-5e3d1088d070', '2026-09-12T10:00:00Z'),
  ('6bb59bf5-f82b-53be-a9b9-0b48c7681a09', '7e0472bd-c496-5fb0-be70-99175fa8757a', 'DEMO · A quiet room for exam season', 'wellbeing', 'DEMO text. During exams there is nowhere calm to sit between papers.', 'DEMO text. Ask the school for one room, set simple rules, and open it for two weeks.', 'DEMO text. A sign-in sheet with first names only, and feedback cards.', 'DEMO text.', 'proposed', 'club', 2026, null, null, '93693c56-8685-5796-a901-f5ca77420a1b', '2026-09-26T10:00:00Z'),
  ('15554f2a-d614-57aa-89ae-0e8367b1265f', '7e0472bd-c496-5fb0-be70-99175fa8757a', 'DEMO · Second-hand uniform swap', 'economy', 'DEMO text. New uniforms cost a lot, and outgrown ones sit in cupboards.', 'DEMO text. A swap rail at parents’ evening, sorted by size.', 'DEMO text. How many items changed hands, and a photo of the rail.', 'DEMO text. Next time: start collecting a month earlier.', 'completed', 'public', 2026, 'a06be9e1-75c4-53a1-99da-2bff395d3434', '2026-06-10T10:00:00Z', '74866792-0bc7-5140-8f41-5e3d1088d070', '2026-05-02T10:00:00Z'),
  ('0e9bc3e0-8471-58b5-8244-c0095eaa822d', '7e0472bd-c496-5fb0-be70-99175fa8757a', 'DEMO · E-waste collection point', 'nature', 'DEMO text. Old chargers and cables end up in the normal bin.', 'DEMO text. A labelled box in the library, emptied by a local recycler.', 'DEMO text. Weight collected each month.', 'DEMO text.', 'proposed', 'public', 2026, null, null, '74866792-0bc7-5140-8f41-5e3d1088d070', '2026-09-27T10:00:00Z'),
  ('f4bdcd57-8545-5901-9307-cd6a45def0a9', 'cf8913b2-c636-5f3c-83ef-13b4c6044f8d', 'DEMO · Food bank drive', 'society', 'DEMO text. The local food bank runs low before the winter holidays.', 'DEMO text. Two collection weeks at school, and one afternoon helping to sort.', 'DEMO text. Boxes collected and a thank-you note from the food bank.', 'DEMO text.', 'active', 'public', 2026, 'a756970b-fe3b-5eb2-aa9e-47439ab03ee1', '2026-09-12T10:00:00Z', '29ca66fc-d2fe-5033-83b5-afaad859763c', '2026-09-08T10:00:00Z'),
  ('591e651b-5539-5de6-8973-815199d7b0f3', '4bb67bf4-3022-5990-907e-867f519348cf', 'DEMO · Repair café', 'economy', 'DEMO text. Broken things get thrown away when a small fix would do.', 'DEMO text. A monthly repair afternoon with volunteers who know how.', 'DEMO text. Items fixed, and what they would have cost to replace.', 'DEMO text.', 'active', 'public', 2026, '952ad586-de0f-52e9-93ea-c6f501f3acc6', '2026-09-01T10:00:00Z', '9a5ee445-3b0d-5bdb-910c-e29366c425a9', '2026-08-29T10:00:00Z'),
  ('79ea0cd1-505b-5778-8f36-0d90e08181df', 'f8db7916-e6b5-5c30-9fa5-c51163c9eb8b', 'DEMO · Walk-and-talk mornings', 'wellbeing', 'DEMO text. Mornings feel rushed and lonely for new students.', 'DEMO text. A short walk around the block before first lesson, twice a week.', 'DEMO text. How many joined, and what they said afterwards.', 'DEMO text.', 'active', 'public', 2026, 'fc1ad2b4-745f-5fbb-b2f1-160ff34b7267', '2026-09-20T10:00:00Z', '7f83cc75-ce0a-5fb8-ab6d-784439e1b42d', '2026-09-19T10:00:00Z'),
  ('646d0a78-ff4b-5561-9cad-3978179d2de9', '051adc3b-3063-5a31-a255-a54827541915', 'DEMO · School garden water audit', 'nature', 'DEMO text. We water the garden every day without knowing how much it needs.', 'DEMO text. Measure, add a rain barrel, and water by schedule.', 'DEMO text. Litres used before and after.', 'DEMO text.', 'active', 'public', 2026, '19d6ed01-30ed-5407-aa17-68efc0419cf9', '2026-09-08T10:00:00Z', '81504807-66d6-5705-9091-b8a288258b9f', '2026-09-06T10:00:00Z'),
  ('7e2e936e-9f08-54f8-8395-1495574bf2e9', '8932304a-ddec-5495-b2ed-6831ab54f9c8', 'DEMO · Buddy scheme for new students', 'society', 'DEMO text. New students take weeks to find their feet.', 'DEMO text. Every new student gets an older buddy for their first month.', 'DEMO text. A short check-in after four weeks.', 'DEMO text.', 'active', 'club', 2026, '72c53e2b-8a94-5c83-bf18-7028c423536b', '2026-09-23T10:00:00Z', '0aca4e59-d199-52d8-8938-c4e328a567ef', '2026-09-22T10:00:00Z');
